stage_a_raw:
{
  "decisions": [
    {
      "decision": "flow_balance_sign_convention",
      "evidence": "\"the total resources shipped into the city plus its supply must equal the total resources shipped out of the city plus its demand\" and \"City 0 has a net demand of 41 units\" / \"City 2 has a net supply of 15 units (indicated by a negative demand of -15)\"",
      "options": [
        "inflow - outflow == demand[i] (positive demand = net consumer)",
        "outflow - inflow == demand[i] (positive demand = net consumer)",
        "inflow - outflow == -demand[i] (positive demand = net consumer)"
      ],
      "plausibility": [
        0.6,
        0.2,
        0.2
      ],
      "majority_option": "inflow - outflow == demand[i] (positive demand = net consumer)"
    },
    {
      "decision": "variable_domain",
      "evidence": "\"All shipments must be non-negative.\" (no integrality stated)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "capacity_constraint_handling",
      "evidence": "\"the amount of resources shipped on any route cannot exceed the maximum capacity for that route\"",
      "options": [
        "upper bound on variable only (x[i,j] <= capacity)",
        "explicit constraint x[i,j] <= capacity plus variable bound",
        "explicit constraint x[i,j] < capacity (strict)"
      ],
      "plausibility": [
        0.5,
        0.45,
        0.05
      ],
      "majority_option": "explicit constraint x[i,j] <= capacity plus variable bound"
    },
    {
      "decision": "arc_set_orientation",
      "evidence": "\"From City 0: To City 1: Cost = 7, Capacity = 35\" (directed routes listed per origin)",
      "options": [
        "directed arcs (i,j) exactly as listed, one variable per listed route",
        "undirected edges with a single variable per pair",
        "directed arcs plus reverse arcs added where not listed"
      ],
      "plausibility": [
        0.85,
        0.1,
        0.05
      ],
      "majority_option": "directed arcs (i,j) exactly as listed, one variable per listed route"
    },
    {
      "decision": "objective_units_and_scale",
      "evidence": "\"minimizing the total transportation cost\" and \"Cost = 7\" per route",
      "options": [
        "sum of cost[i,j] * x[i,j] in raw cost units",
        "sum of cost[i,j] * x[i,j] scaled (e.g. per-unit cost times quantity in thousands)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "sum of cost[i,j] * x[i,j] in raw cost units"
    },
    {
      "decision": "redundant_balance_consistency",
      "evidence": "\"the total flow of resources into and out of each city must balance according to their respective requirements\" (total demand 66 equals total supply 66)",
      "options": [
        "enforce balance on all 9 cities (one is redundant)",
        "enforce balance on 8 cities and drop one as redundant"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "enforce balance on all 9 cities (one is redundant)"
    }
  ]
}
